 21→// Cursor hook names - these become subcommands under `entire hooks cursor`
 22→const (
 23→	HookNameSessionStart       = "session-start"
 24→	HookNameSessionEnd         = "session-end"
 25→	HookNameBeforeSubmitPrompt = "before-submit-prompt"
 26→	HookNameStop               = "stop"
 27→	HookNamePreCompact         = "pre-compact"
 28→	HookNameSubagentStart      = "subagent-start"
 29→	HookNameSubagentStop       = "subagent-stop"
 30→)
 31→
 32→// HooksFileName is the hooks file used by Cursor.
 33→const HooksFileName = "hooks.json"
 34→
 35→// entireHookPrefixes are command prefixes that identify Entire hooks
 36→var entireHookPrefixes = []string{
 37→	"entire ",
 38→	"go run ${CURSOR_PROJECT_DIR}/cmd/entire/main.go ",
 39→}
 40→
 41→// HookNames returns the hook verbs Cursor supports.
 42→// These become subcommands: entire hooks cursor <verb>
 43→func (c *CursorAgent) HookNames() []string {
 44→	return []string{
 45→		HookNameSessionStart,
 46→		HookNameSessionEnd,
 47→		HookNameBeforeSubmitPrompt,
 48→		HookNameStop,
 49→		HookNamePreCompact,
 50→		HookNameSubagentStart,
 51→		HookNameSubagentStop,
 52→	}
 53→}
