279→// AreHooksInstalled checks if Entire hooks are installed.
280→func (c *CursorAgent) AreHooksInstalled(ctx context.Context) bool {
281→	worktreeRoot, err := paths.WorktreeRoot(ctx)
282→	if err != nil {
283→		worktreeRoot = "."
284→	}
285→	hooksPath := filepath.Join(worktreeRoot, ".cursor", HooksFileName)
286→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
287→	if err != nil {
288→		return false
289→	}
290→
291→	var hooksFile CursorHooksFile
292→	if err := json.Unmarshal(data, &hooksFile); err != nil {
293→		return false
294→	}
295→
296→	return hasEntireHook(hooksFile.Hooks.SessionStart) ||
297→		hasEntireHook(hooksFile.Hooks.SessionEnd) ||
298→		hasEntireHook(hooksFile.Hooks.BeforeSubmitPrompt) ||
299→		hasEntireHook(hooksFile.Hooks.Stop) ||
300→		hasEntireHook(hooksFile.Hooks.PreCompact) ||
301→		hasEntireHook(hooksFile.Hooks.SubagentStart) ||
302→		hasEntireHook(hooksFile.Hooks.SubagentStop)
303→}
