 25→type Gemini struct{}
 26→
 27→func (g *Gemini) Name() string               { return "gemini-cli" }
 28→func (g *Gemini) Binary() string             { return "gemini" }
 29→func (g *Gemini) EntireAgent() string        { return "gemini" }
 30→func (g *Gemini) PromptPattern() string      { return `Type your message` }
 31→func (g *Gemini) TimeoutMultiplier() float64 { return 2.5 }
