 33→func (g *Gemini) IsTransientError(out Output, err error) bool {
 34→	if errors.Is(err, context.DeadlineExceeded) {
 35→		return true
 36→	}
 37→	transientPatterns := []string{
 38→		"INTERNAL",
 39→		"Incomplete JSON segment",
 40→		"429",
 41→		"TooManyRequests",
 42→		"RESOURCE_EXHAUSTED",
 43→		"UNAVAILABLE",
 44→		"DEADLINE_EXCEEDED",
 45→		"unexpected critical error",
 46→	}
 47→	for _, p := range transientPatterns {
 48→		if strings.Contains(out.Stderr, p) {
 49→			return true
 50→		}
 51→	}
 52→	return false
 53→}
