110→// ForEachAgent runs fn as a parallel subtest for every registered agent.
111→// It handles repo setup, concurrency gating, context timeout, and cleanup.
112→// The timeout is scaled by each agent's TimeoutMultiplier.
113→//
114→// If RunPrompt detects a transient API error (e.g. rate limit, token refresh
115→// failure), it panics with errScenarioRestart. ForEachAgent recovers from the
116→// panic and restarts the entire scenario with a fresh repository, up to
117→// maxScenarioRestarts times. This avoids stale CLI session state from the
118→// failed attempt poisoning the retry.
119→func ForEachAgent(t *testing.T, timeout time.Duration, fn func(t *testing.T, s *RepoState, ctx context.Context)) {
120→	t.Helper()
121→	t.Parallel()
122→	all := agents.All()
123→	if len(all) == 0 {
124→		t.Skip("no agents registered (check E2E_AGENT filter)")
125→	}
126→	for _, agent := range all {
127→		t.Run(agent.Name(), func(t *testing.T) {
128→			// Use the global test deadline for slot wait so we don't
129→			// skip prematurely — only bail if the whole binary is dying.
130→			slotCtx := context.Background()
131→			if deadline, ok := t.Deadline(); ok {
132→				var cancel context.CancelFunc
133→				slotCtx, cancel = context.WithDeadline(slotCtx, deadline)
134→				defer cancel()
135→			}
136→			if err := agents.AcquireSlot(slotCtx, agent); err != nil {
137→				t.Fatalf("timed out waiting for agent slot: %v", err)
138→			}
139→			defer agents.ReleaseSlot(agent)
140→
141→			// Per-test timeout starts after slot is acquired, scaled
142→			// by the agent's multiplier (e.g. 2.5× for gemini).
143→			scaled := time.Duration(float64(timeout) * agent.TimeoutMultiplier())
144→
145→			var prevState *RepoState
146→			for attempt := range maxScenarioRestarts + 1 {
147→				s := SetupRepo(t, agent)
148→				ctx, cancel := context.WithTimeout(context.Background(), scaled)
149→
150→				// On restart, suppress artifact capture from the previous
151→				// failed attempt so it doesn't overwrite the final one.
152→				if prevState != nil {
153→					prevState.skipArtifacts = true
154→				}
155→
156→				restarted := runScenario(t, s, ctx, fn)
157→				cancel()
158→
159→				if !restarted {
160→					return
161→				}
162→				prevState = s
163→				if attempt >= maxScenarioRestarts {
164→					t.Fatalf("exhausted %d scenario attempts due to transient API errors", maxScenarioRestarts+1)
165→				}
166→				t.Logf("transient error, restarting scenario (attempt %d/%d)", attempt+2, maxScenarioRestarts+1)
167→			}
168→		})
169→	}
170→}
171→
172→// runScenario runs the test function and recovers from errScenarioRestart
173→// panics triggered by transient API errors in RunPrompt. Returns true if
174→// the scenario should be restarted with a fresh repository.
175→func runScenario(t *testing.T, s *RepoState, ctx context.Context, fn func(t *testing.T, s *RepoState, ctx context.Context)) (restarted bool) {
176→	t.Helper()
177→	defer func() {
178→		if r := recover(); r != nil {
179→			if _, ok := r.(errScenarioRestart); ok {
180→				restarted = true
181→				return
182→			}
183→			panic(r) // re-panic for unexpected panics
184→		}
185→	}()
186→	fn(t, s, ctx)
187→	return false
188→}
189→
190→const maxScenarioRestarts = 2 // restart up to 2 times = 3 total attempts
191→
192→// errScenarioRestart is panicked by RunPrompt when a transient API error is
193→// detected. ForEachAgent recovers from this panic and restarts the test
194→// scenario with a fresh repository, avoiding stale CLI state from the failed
195→// attempt.
196→type errScenarioRestart struct {
197→	msg string
198→}
199→
200→// RunPrompt runs an agent prompt, logs the command and output to ConsoleLog,
201→// and returns the result. If the agent reports a transient API error, it
202→// panics with errScenarioRestart to trigger a full scenario restart in
203→// ForEachAgent (see runScenario).
204→func (s *RepoState) RunPrompt(t *testing.T, ctx context.Context, prompt string, opts ...agents.Option) (agents.Output, error) {
205→	t.Helper()
206→	out, err := s.Agent.RunPrompt(ctx, s.Dir, prompt, opts...)
207→	s.logPromptResult(out)
208→
209→	if err != nil && s.Agent.IsTransientError(out, err) {
210→		errMsg := fmt.Sprintf("transient API error (stderr: %s)", strings.TrimSpace(out.Stderr))
211→		t.Logf("%s — restarting scenario", errMsg)
212→		fmt.Fprintf(s.ConsoleLog, "> [transient] %s — restarting scenario\n", errMsg)
213→		panic(errScenarioRestart{msg: errMsg})
214→	}
215→
216→	return out, err
217→}
