269→// PatchSettings merges extra keys into .entire/settings.json.
270→func PatchSettings(t *testing.T, dir string, extra map[string]any) {
271→	t.Helper()
272→	path := filepath.Join(dir, ".entire", "settings.json")
273→	data, err := os.ReadFile(path)
