345→// CheckpointIDs lists all checkpoint IDs from the tree at the tip of the
346→// checkpoint branch. It parses the two-level directory structure
347→// ({prefix}/{suffix}/metadata.json) and returns the concatenated IDs.
348→func CheckpointIDs(t *testing.T, dir string) []string {
349→	t.Helper()
350→	out := gitOutputSafe(dir, "ls-tree", "-r", "--name-only", "entire/checkpoints/v1")
351→	if out == "" {
352→		return nil
353→	}
354→	seen := map[string]bool{}
355→	var ids []string
356→	for _, line := range strings.Split(strings.TrimSpace(out), "\n") {
357→		// Match {prefix}/{suffix}/metadata.json (top-level, not session-level)
358→		parts := strings.Split(line, "/")
359→		if len(parts) == 3 && parts[2] == "metadata.json" {
360→			id := parts[0] + parts[1]
361→			if !seen[id] {
362→				seen[id] = true
363→				ids = append(ids, id)
364→			}
365→		}
366→	}
367→	return ids
368→}
