406→// WaitForSessionMetadata polls until session metadata exists on the checkpoint
407→// branch for the given checkpoint ID and session index, then returns it.
408→// This handles the race where the checkpoint branch advances before session
409→// metadata is fully committed.
410→func WaitForSessionMetadata(t *testing.T, dir string, checkpointID string, sessionIndex int, timeout time.Duration) SessionMetadata {
411→	t.Helper()
412→
413→	path := fmt.Sprintf("%s/%d/metadata.json", CheckpointPath(checkpointID), sessionIndex)
414→	blob := "entire/checkpoints/v1:" + path
415→
416→	deadline := time.Now().Add(timeout)
417→	for time.Now().Before(deadline) {
418→		raw := gitOutputSafe(dir, "show", blob)
419→		if raw != "" {
420→			var meta SessionMetadata
421→			if err := json.Unmarshal([]byte(raw), &meta); err != nil {
422→				t.Fatalf("unmarshal session metadata from %s: %v", blob, err)
423→			}
424→			return meta
425→		}
426→		time.Sleep(500 * time.Millisecond)
427→	}
428→	t.Fatalf("session metadata %s did not appear within %s", blob, timeout)
429→	return SessionMetadata{}
430→}
