package agents

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"syscall"
	"time"
)

func init() {
	if env := os.Getenv("E2E_AGENT"); env != "" && env != "cursor-cli" {
		return
	}
	if _, err := exec.LookPath("agent"); err != nil {
		return
	}
	Register(&CursorCLI{})
}

// CursorCLI implements the E2E Agent interface for the Cursor Agent CLI binary.
// The CLI binary is called "agent" and uses Cursor's hooks system via
// .cursor/hooks.json. It maps to the same Entire agent as Cursor IDE ("cursor").
//
// Key limitation: in headless (-p) mode, the beforeSubmitPrompt and stop hooks
// do NOT fire. Only sessionStart, sessionEnd, and tool-use hooks fire. This
// means RunPrompt-based tests won't get TurnStart/TurnEnd events. Interactive
// tmux-based tests get the full lifecycle.
type CursorCLI struct{}

func (a *CursorCLI) Name() string               { return "cursor-cli" }
func (a *CursorCLI) Binary() string             { return "agent" }
func (a *CursorCLI) EntireAgent() string        { return "cursor" }
func (a *CursorCLI) TimeoutMultiplier() float64 { return 1.5 }

// PromptPattern returns a regex matching the Cursor CLI's TUI input prompt.
// The CLI shows ">" when ready for input in interactive mode.
func (a *CursorCLI) PromptPattern() string { return `>` }

func (a *CursorCLI) IsTransientError(out Output, err error) bool {
	if err == nil {
		return false
	}
	if errors.Is(err, context.DeadlineExceeded) {
		return true
	}
	combined := out.Stdout + out.Stderr
	for _, p := range []string{
		"overloaded",
		"rate limit",
		"429",
		"503",
		"529",
		"ECONNRESET",
		"ETIMEDOUT",
		"server error",
		"Internal Server Error",
	} {
		if strings.Contains(combined, p) {
			return true
		}
	}
	return false
}

func (a *CursorCLI) Bootstrap() error {
	// The Cursor CLI authenticates via CURSOR_API_KEY env var or OAuth.
	// On CI, ensure CURSOR_API_KEY is set. Locally, OAuth/keychain works.
	if os.Getenv("CI") != "" && os.Getenv("CURSOR_API_KEY") == "" {
		return fmt.Errorf("CURSOR_API_KEY must be set on CI for cursor-cli E2E tests")
	}
	return nil
}

func (a *CursorCLI) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
	cfg := &runConfig{}
	for _, o := range opts {
		o(cfg)
	}

	// Per-prompt timeout so a slow response gets killed early enough to
	// retry within the test's overall budget.
	timeout := 90 * time.Second
	if cfg.PromptTimeout > 0 {
		timeout = cfg.PromptTimeout
	}
	promptCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	args := []string{"-p", prompt, "--force", "--trust", "--workspace", dir}
	displayArgs := []string{"-p", fmt.Sprintf("%q", prompt), "--force", "--trust", "--workspace", dir}

	if cfg.Model != "" {
		args = append(args, "--model", cfg.Model)
		displayArgs = append(displayArgs, "--model", cfg.Model)
	}

	cmd := exec.CommandContext(promptCtx, a.Binary(), args...)
	cmd.Dir = dir
	cmd.Stdin = nil
	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	cmd.Cancel = func() error {
		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
	}
	cmd.WaitDelay = 5 * time.Second

	var stdout, stderr strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()
	exitCode := 0
	if err != nil {
		exitErr := &exec.ExitError{}
		if errors.As(err, &exitErr) {
			exitCode = exitErr.ExitCode()
		} else {
			exitCode = -1
		}
		// Wrap the prompt-level deadline so IsTransientError can detect it.
		if promptCtx.Err() == context.DeadlineExceeded {
			err = fmt.Errorf("%w: %w", err, context.DeadlineExceeded)
		}
	}

	return Output{
		Command:  a.Binary() + " " + strings.Join(displayArgs, " "),
		Stdout:   stdout.String(),
		Stderr:   stderr.String(),
		ExitCode: exitCode,
	}, err
}

func (a *CursorCLI) StartSession(ctx context.Context, dir string) (Session, error) {
	name := fmt.Sprintf("cursor-cli-test-%d", time.Now().UnixNano())
	s, err := NewTmuxSession(name, dir, nil, a.Binary(), "--force", "--workspace", dir)
	if err != nil {
		return nil, err
	}

	// Wait for the TUI to be ready (input prompt).
	if _, err := s.WaitFor(`>`, 30*time.Second); err != nil {
		_ = s.Close()
		return nil, fmt.Errorf("waiting for startup prompt: %w", err)
	}
	s.stableAtSend = ""

	return s, nil
}

